{
  "decision": "REVISE",
  "detail": {
    "days": 14,
    "checkpoint": "Your meaningful stopping point"
  },
  "plans": [
    {
      "planRef": "plan_1",
      "blueprint": {
        "schemaVersion": 2,
        "strategy": {
          "policy": "GENERAL",
          "outcome": "The accepted outcome",
          "explanation": "Your educational judgment",
          "recommendedEffort": {
            "lowMinutes": 5,
            "likelyMinutes": 10,
            "highMinutes": 20
          },
          "phases": []
        },
        "scope": [
          {
            "scopeRef": "scope_1",
            "disposition": "INCLUDED",
            "contribution": "Its specific contribution"
          }
        ],
        "activities": [
          {
            "localId": "work",
            "outcomeRefs": [],
            "scopeRefs": [
              "scope_1"
            ],
            "title": "Your specific activity",
            "activityType": "Your chosen activity type",
            "purpose": "Its distinct contribution",
            "instructions": "Concrete learner instructions",
            "completionCriterion": "Observable outcome",
            "effort": {
              "lowMinutes": 5,
              "likelyMinutes": 10,
              "highMinutes": 20
            },
            "timeboxMinutes": 10,
            "commitment": {
              "category": "COMMITTED"
            },
            "hardDependencies": []
          }
        ],
        "decisions": {
          "assumptions": [],
          "tradeOffs": [],
          "unresolvedUncertainty": [],
          "stoppingConditions": []
        }
      }
    }
  ],
  "sharedDependencies": [],
  "tradeOffExplanation": "Your concrete trade-off"
